const API_URL = 'http://localhost:3000/api/tasks';

// Helper to handle standardizing responses safely
const handleResponse = async (response) => {
  // 1. Check if the backend sent JSON
  const contentType = response.headers.get("content-type");
  if (!contentType || !contentType.includes("application/json")) {
    const text = await response.text();
    console.error("Non-JSON response from server:", text);
    throw new Error("Server connection failed. Is the backend running on port 5000?");
  }

  // 2. Parse JSON safely
  const data = await response.json();
  if (!response.ok) {
    throw new Error(`[Error ${response.status}] ${data.message || 'Something went wrong'}`);
  }
  return data;
};

export const fetchTasks = async (statusFilter = 'all') => {
  const url = statusFilter !== 'all' ? `${API_URL}?status=${statusFilter}` : API_URL;
  const response = await fetch(url);
  return handleResponse(response);
};

export const createTask = async (taskData) => {
  const response = await fetch(API_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(taskData),
  });
  return handleResponse(response);
};

export const updateTaskStatus = async (id, status) => {
  const response = await fetch(`${API_URL}/${id}`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ status }),
  });
  return handleResponse(response);
};

export const deleteTask = async (id) => {
  const response = await fetch(`${API_URL}/${id}`, {
    method: 'DELETE',
  });
  return handleResponse(response);
};
